"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

type InvitationProps = Omit<React.ComponentProps<"button">, "children"> & {
  label: string
  hint?: string
  state?: string
}

/** The way into a conversation, held in the margin until the conversation itself comes into view. */
function Invitation({ label, hint, state, className, ...props }: InvitationProps) {
  const [away, setAway] = React.useState(false)
  React.useEffect(() => {
    const visible = new Set<Element>()
    const watched = new Set<Element>()
    const observer = new IntersectionObserver((entries) => {
      for (const entry of entries) {
        if (entry.isIntersecting) visible.add(entry.target)
        else visible.delete(entry.target)
      }
      setAway(visible.size > 0)
    })
    const scan = () => {
      for (const el of watched) {
        if (el.isConnected && el.hasAttribute("data-invitation-hide")) continue
        observer.unobserve(el)
        watched.delete(el)
        visible.delete(el)
      }
      document.querySelectorAll("[data-invitation-hide]").forEach((el) => {
        if (watched.has(el)) return
        watched.add(el)
        observer.observe(el)
      })
      setAway(visible.size > 0)
    }
    scan()
    const changed = new MutationObserver(scan)
    changed.observe(document.body, { childList: true, subtree: true, attributes: true, attributeFilter: ["data-invitation-hide"] })
    return () => { observer.disconnect(); changed.disconnect() }
  }, [])
  return (
    <button type="button" data-slot="invitation" className={cn("db-invitation", className)} {...props} data-away={away || undefined} inert={away} aria-hidden={away || undefined}>
      <span className="db-invitation-call"><span>{label}</span><span className="db-invitation-arrow" aria-hidden="true">→</span></span>
      {state ? <span className="db-invitation-state db-reading">{state}</span> : hint ? <span className="db-invitation-hint">{hint}</span> : null}
    </button>
  )
}

export { Invitation, type InvitationProps }

@layer components {
  /* "Watch this space": one line in the margin, opening a conversation. It sits on paper, so the page
     scrolling beneath never shows through its words. */
  .db-invitation {
    position: fixed; z-index: 20; inset-inline-end: calc(var(--db-margin) - var(--db-space-3)); inset-block-end: var(--db-space-5);
    display: grid; justify-items: start; gap: var(--db-space-1); max-inline-size: calc(100% - 2 * var(--db-margin));
    appearance: none; border: 0; padding: var(--db-space-3); background: var(--db-paper); color: var(--db-ink); cursor: pointer;
    font: inherit; font-size: var(--db-p); text-align: start;
    transition: translate var(--db-moderato) var(--db-exhale), opacity var(--db-moderato), visibility var(--db-moderato);
  }
  .db-invitation-call { display: flex; align-items: baseline; gap: var(--db-space-4); }
  .db-invitation-arrow { display: inline-block; color: var(--db-pencil); }
  .db-invitation-arrow:is([dir="rtl"], [dir="rtl"] *) { scale: -1 1; }
  .db-invitation-hint { font-size: var(--db-pp); color: var(--db-pencil); }
  .db-invitation-state { font-family: var(--db-expression); font-style: italic; font-size: var(--db-p); }
  .db-invitation:is(:hover, [data-force~="hover"]) .db-invitation-call { text-decoration: underline; text-underline-offset: 0.25em; }
  .db-invitation:focus-visible, .db-invitation[data-force~="focus"] { outline: var(--db-stroke) solid var(--db-accent); outline-offset: var(--db-space-2); }
  .db-invitation[data-away] { translate: 0 -1em; opacity: 0; visibility: hidden; pointer-events: none; }
  .db-invitation:disabled { color: var(--db-pencil); cursor: not-allowed; }
  @media (max-width: 40rem) {
    .db-invitation { inset-inline: 0; inset-block-end: 0; max-inline-size: none; inline-size: 100%; border-block-start: var(--db-hairline) solid var(--db-rule-strong); padding: var(--db-space-4) var(--db-margin) calc(var(--db-space-4) + env(safe-area-inset-bottom)); }
    .db-invitation-call { inline-size: 100%; justify-content: space-between; }
  }
  @media (prefers-reduced-motion: reduce) { .db-invitation[data-away] { translate: none; } }
  @media (forced-colors: active) { .db-invitation { color: ButtonText; border-color: ButtonText; } .db-invitation:focus-visible { outline-color: Highlight; } }
}
